"use client";
import {useEffect,useState} from "react";
import Link from "next/link";
import {api,ApiError} from "@/lib/api-client";

type Campaign={id:string;productId:string;name:string;slug:string;comingSoon?:boolean;launchAt:string;status:string;homepage:boolean;flashDealId:string|null;launchedAt:string|null};
type VendorProduct={id:string;name:string;slug:string;status:string;comingSoon?:boolean;availableAt?:string|null;stock:number};
export default function LaunchCampaignsPage(){const[c,setC]=useState<Campaign[]>([]);const[products,setProducts]=useState<VendorProduct[]>([]);const[productId,setProductId]=useState("");const[launchAt,setLaunchAt]=useState("");const[homepage,setHomepage]=useState(true);const[busy,setBusy]=useState(false);const[activating,setActivating]=useState<string|null>(null);const[error,setError]=useState<string|null>(null);const load=()=>{api.get<{campaigns:Campaign[]}>('/api/launch-campaigns/mine').then(r=>setC(r.campaigns)).catch(()=>setC([]));api.get<{products:VendorProduct[]}>('/api/products/mine').then(r=>setProducts(r.products??[])).catch(()=>setProducts([]));};useEffect(load,[]);const create=async()=>{if(!productId||!launchAt)return;setError(null);setBusy(true);try{await api.post('/api/launch-campaigns',{productId,launchAt:new Date(launchAt).toISOString(),homepage});setProductId('');setLaunchAt('');load();}catch(err){setError(err instanceof ApiError?err.message:'Unable to schedule this launch.');}finally{setBusy(false);}};const makeAvailable=async(id:string)=>{setError(null);setActivating(id);try{await api.post(`/api/launch-campaigns/product/${id}/activate`,{});load();}catch(err){setError(err instanceof ApiError?err.message:'Unable to make this product available.');}finally{setActivating(null);}};const action=async(id:string,type:'launch'|'cancel')=>{setError(null);try{await api.post(`/api/launch-campaigns/${id}/${type}`,{});load();}catch(err){setError(err instanceof ApiError?err.message:'Unable to update this campaign.');}};const comingSoonProducts=products.filter(p=>p.status==='ACTIVE'&&p.comingSoon);return <div className="shell py-8"><div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-ember-600">Growth</p><h1 className="mt-1 text-xl font-bold text-graphite-900 dark:text-white">Launch campaigns</h1><p className="mt-1 text-sm text-graphite-600 dark:text-graphite-400">Build anticipation for a Coming Soon product or schedule the launch of an existing product.</p></div><Link href="/vendor/dashboard/products/new/coming-soon" className="inline-flex items-center justify-center rounded-card bg-ember-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-ember-700">+ Create Coming Soon product</Link></div>{comingSoonProducts.length>0&&<div className="mt-6 rounded-card border border-ember-200 bg-ember-50/60 p-5 dark:border-ember-900/60 dark:bg-ember-950/20"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-ember-600">Coming Soon products</p><h2 className="mt-1 font-semibold text-graphite-900 dark:text-white">Ready to launch?</h2><p className="mt-1 text-xs text-graphite-600 dark:text-graphite-400">Your active Coming Soon products appear here. Make one available immediately or schedule a launch campaign.</p></div><div className="mt-4 grid gap-2">{comingSoonProducts.map(p=><div key={p.id} className="flex flex-col gap-3 rounded-card border border-graphite-200 bg-white p-3 sm:flex-row sm:items-center sm:justify-between dark:border-graphite-700 dark:bg-graphite-900"><div><p className="text-sm font-semibold text-graphite-900 dark:text-white">{p.name}</p><p className="mt-0.5 text-xs text-graphite-500 dark:text-graphite-400">{p.availableAt?`Expected ${new Date(p.availableAt).toLocaleString()}`:'No availability date set'}</p></div><button onClick={()=>makeAvailable(p.id)} disabled={activating===p.id} className="rounded-card bg-ember-600 px-4 py-2 text-sm font-semibold text-white hover:bg-ember-700 disabled:opacity-50">{activating===p.id?'Making available…':'Make available'}</button></div>)}</div></div>}<div className="mt-6 rounded-card border border-graphite-200 p-5 dark:border-graphite-700"><h2 className="font-semibold text-graphite-900 dark:text-white">Schedule a launch</h2><p className="mt-1 text-xs text-graphite-500 dark:text-graphite-400">Choose any active product, including one already marked Coming Soon. When the campaign goes live, the Coming Soon status is removed automatically.</p><div className="mt-4 grid gap-3 sm:grid-cols-3"><select value={productId} onChange={e=>setProductId(e.target.value)} className="rounded-card border border-graphite-300 bg-white px-3 py-2 dark:border-graphite-700 dark:bg-graphite-900 dark:text-white"><option value="">Select product</option>{products.filter(p=>p.status==='ACTIVE').map(p=><option key={p.id} value={p.id}>{p.name}{p.comingSoon?' — Coming Soon':''})</option>)}</select><input type="datetime-local" value={launchAt} onChange={e=>setLaunchAt(e.target.value)} className="rounded-card border border-graphite-300 bg-white px-3 py-2 dark:border-graphite-700 dark:bg-graphite-900 dark:text-white"/><label className="flex items-center gap-2 text-sm text-graphite-700 dark:text-graphite-300"><input type="checkbox" checked={homepage} onChange={e=>setHomepage(e.target.checked)}/> Homepage placement</label></div>{error&&<p role="alert" className="mt-3 rounded-[7px] bg-ember-100 px-3 py-2 text-sm text-ember-700">{error}</p>}<button disabled={busy||!productId||!launchAt} onClick={create} className="mt-4 rounded-card bg-ember-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">{busy?'Scheduling…':'Schedule launch'}</button></div><div className="mt-8"><h2 className="mb-3 text-sm font-bold uppercase tracking-wide text-graphite-600">Campaigns</h2><div className="flex flex-col gap-2">{c.length===0?<p className="text-sm text-graphite-600">No launch campaigns yet.</p>:c.map(x=><div key={x.id} className="flex flex-col gap-3 rounded-card border border-graphite-200 p-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-graphite-900 dark:text-white">{x.name}</p>{x.comingSoon&&<span className="rounded-full bg-cloud-100 px-2 py-0.5 text-[11px] font-semibold text-graphite-700 dark:bg-graphite-800 dark:text-graphite-200">Coming Soon</span>}</div><p className="text-sm text-graphite-600 dark:text-graphite-400">{new Date(x.launchAt).toLocaleString()} · {x.status}{x.homepage?' · Homepage':''}</p></div>{x.status==='SCHEDULED'&&<div className="flex gap-2"><button onClick={()=>action(x.id,'launch')} className="rounded-card bg-ember-600 px-3 py-2 text-sm font-semibold text-white">Launch now</button><button onClick={()=>action(x.id,'cancel')} className="rounded-card border border-graphite-300 px-3 py-2 text-sm font-semibold text-graphite-800 dark:border-graphite-700 dark:text-white">Cancel</button></div>}</div>)}</div></div></div>}
